// Prop registry: all imported art sets, plus the shared decoder.
// Data modules are auto-generated by test/tools/import-props.mjs.

import { CITY_BUILDINGS } from './city_buildings.js';
import { CLEAN_BUILDINGS } from './clean_buildings.js';
import { STREET_PROPS } from './street_props.js';

export const PROP_SETS = {
  city: CITY_BUILDINGS,
  clean: CLEAN_BUILDINGS,
  street: STREET_PROPS,
};

export function getProp(ref) {
  const arr = PROP_SETS[ref.set || 'city'];
  return (arr && arr[ref.i]) || null;
}

export function findPropRef(def) {
  for (const [set, arr] of Object.entries(PROP_SETS)) {
    const i = arr.indexOf(def);
    if (i >= 0) return { set, i };
  }
  return null;
}

const b64decode = (s) => {
  if (typeof atob === 'function') {
    const bin = atob(s);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
  }
  return new Uint8Array(Buffer.from(s, 'base64'));
};

const cache = new Map();
export function decodeProp(def) {
  let dec = cache.get(def);
  if (dec) return dec;
  const idx = b64decode(def.data);
  const mats = new Uint8Array(def.w * def.h);
  const colors = new Uint32Array(def.w * def.h); // 0xRRGGBB where mats>0
  for (let i = 0; i < idx.length; i++) {
    const pi = idx[i];
    if (!pi) continue;
    const q = def.palette[pi - 1];
    mats[i] = def.mats[pi - 1];
    const r = ((q >> 8) & 15) * 17, g = ((q >> 4) & 15) * 17, b = (q & 15) * 17;
    colors[i] = (r << 16) | (g << 8) | b;
  }
  dec = { w: def.w, h: def.h, mats, colors };
  cache.set(def, dec);
  return dec;
}
